  static const int WIFI_REASON_DISASSOC_STA_HAS_LEFT = 8;

  /// STA requesting (re)association is not authenticated with responding STA
  static const int WIFI_REASON_STA_REQ_ASSOC_WITHOUT_AUTH = 9;

  /// Disassociated because the information in the Power Capability
  /// element is unacceptable
  static const int WIFI_REASON_PWR_CAPABILITY_NOT_VALID = 10;

  /// Disassociated because the information in the Supported Channels
  /// element is unacceptable
  static const int WIFI_REASON_SUPPORTED_CHANNEL_NOT_VALID = 11;

  /// Invalid element i.e., an element defined in this standard for which the
  /// content does not meet the specifications in Clause 8
  static const int WIFI_REASON_INVALID_IE = 13;

  /// Message Integrity Code (MIC) failure
  static const int WIFI_REASON_MICHAEL_MIC_FAILURE = 14;

  /// 4-Way Handshake timeout
  static const int WIFI_REASON_4WAY_HANDSHAKE_TIMEOUT = 15;

  /// Group Key Handshake timeout
  static const int WIFI_REASON_GROUP_KEY_UPDATE_TIMEOUT = 16;

  /// Element in 4-Way Handshake different from (Re)Association Request/Probe
  /// Response/Beacon frame
  static const int WIFI_REASON_IE_IN_4WAY_DIFFERS = 17;

  /// Invalid group cipher
  static const int WIFI_REASON_GROUP_CIPHER_NOT_VALID = 18;

  /// Invalid pairwise cipher
  static const int WIFI_REASON_PAIRWISE_CIPHER_NOT_VALID = 19;

  /// Invalid AKMP
  static const int WIFI_REASON_AKMP_NOT_VALID = 20;

  /// Unsupported RSNE version
  static const int WIFI_REASON_UNSUPPORTED_RSN_IE_VERSION = 21;

  /// Invalid RSNE capabilities
  static const int WIFI_REASON_INVALID_RSN_IE_CAPAB = 22;

  /// IEEE 802.1X authentication failed
  static const int WIFI_REASON_IEEE_802_1X_AUTH_FAILED = 23;

  /// Cipher suite rejected because of the security policy
  static const int WIFI_REASON_CIPHER_SUITE_REJECTED = 24;

  /// TDLS direct-link teardown due to TDLS peer STA unreachable via the
  /// TDLS direct link
  static const int WIFI_REASON_TDLS_TEARDOWN_UNREACHABLE = 25;

  /// TDLS direct-link teardown for unspecified reason
  static const int WIFI_REASON_TDLS_TEARDOWN_UNSPECIFIED = 26;

  /// Disassociated because excessive number of frames need to be acknowledged,
  /// but are not acknowledged due to AP transmissions and/or poor channel conditions
  static const int WIFI_REASON_DISASSOC_LOW_ACK = 34;

  /// SME cancels the mesh peering instance with the reason other than reaching
  /// the maximum number of peer mesh STAs
  static const int WIFI_REASON_MESH_PEERING_CANCELLED = 52;

  /// The mesh STA has reached the supported maximum number of peer mesh STAs
  static const int WIFI_REASON_MESH_MAX_PEERS = 53;

  /// The received information violates the Mesh Configuration policy
  /// configured in the mesh STA profile
  static const int WIFI_REASON_MESH_CONFIG_POLICY_VIOLATION = 54;

  /// The mesh STA has received a Mesh Peering Close message requesting
  /// to close the mesh peering
  static const int WIFI_REASON_MESH_CLOSE_RCVD = 55;

  /// The mesh STA has resent dot11MeshMaxRetries Mesh Peering Open messages,
  /// without receiving a Mesh Peering Confirm message
  static const int WIFI_REASON_MESH_MAX_RETRIES = 56;

  /// The confirmTimer for the mesh peering instance times out
  static const int WIFI_REASON_MESH_CONFIRM_TIMEOUT = 57;

  /// The mesh STA fails to unwrap the GTK or the values in the wrapped
  /// contents do not match
  static const int WIFI_REASON_MESH_INVALID_GTK = 58;

  /// The mesh STA receives inconsistent information about the mesh parameters
  /// between Mesh Peering Management frames
  static const int WIFI_REASON_MESH_INCONSISTENT_PARAMS = 59;

  /// The mesh STA does not have proxy information for this external destination
  static const int WIFI_REASON_MESH_INVALID_SECURITY_CAP = 60;
}

/// @brief Enumeration for Wi-Fi Association Status code, provided by the supplicant.
/// @details The Wi-Fi Standard Reference : Status codes (IEEE 802.11-2007, 7.3.1.9, Table 7-23).
/// @since_tizen 5.0
abstract class wifi_manager_assoc_status_code_e {
  /// Successful
  static const int WLAN_STATUS_SUCCESS = 0;

  /// Unspecified failure
  static const int WLAN_STATUS_UNSPECIFIED_FAILURE = 1;

  /// Responding STA does not support the specified authentication
  /// algorithm
  static const int WLAN_STATUS_NOT_SUPPORTED_AUTH_ALG = 13;

  /// Association denied because AP is unable to handle additional
  /// associated STAs
  static const int WLAN_STATUS_AP_UNABLE_TO_HANDLE_NEW_STA = 17;

  /// Association denied because the requesting STA does not support
  /// HT feature
  static const int WLAN_STATUS_ASSOC_DENIED_NO_HT = 27;

  /// Association request rejected temporarily
  static const int WLAN_STATUS_ASSOC_REJECTED_TEMPORARILY = 30;

  /// Robust management frame policy violation
  static const int WLAN_STATUS_ROBUST_MGMT_FRAME_POLICY_VIOLATION = 31;

  /// Invalid element
  static const int WLAN_STATUS_INVALID_IE = 40;

  /// Invalid group cipher
  static const int WLAN_STATUS_GROUP_CIPHER_NOT_VALID = 41;

  /// Invalid pairwise cipher
  static const int WLAN_STATUS_PAIRWISE_CIPHER_NOT_VALID = 42;

  /// Invalid AKMP
  static const int WLAN_STATUS_AKMP_NOT_VALID = 43;

  /// Cipher suite rejected because of security policy
  static const int WLAN_STATUS_CIPHER_REJECTED_PER_POLICY = 46;

  /// Association denied because the Listen interval is too large
  static const int WLAN_STATUS_ASSOC_DENIED_LISTEN_INT_TOO_LARGE = 51;

  /// Invalid pairwise master key identifier (PKMID)
  static const int WLAN_STATUS_INVALID_PMKID = 53;

  /// Invalid MDE
  static const int WLAN_STATUS_INVALID_MDIE = 54;

  /// Invalid FTE
  static const int WLAN_STATUS_INVALID_FTIE = 55;

  /// Association denied because the requesting STA does not support
  /// VHT feature
  static const int WLAN_STATUS_ASSOC_DENIED_NO_VHT = 104;
}

/// @brief Enumeration for the state of the Wi-Fi TDLS.
/// @since_tizen 3.0
abstract class wifi_manager_tdls_state_e {
  /// < Wi-Fi TDLS is Disconnected
  static const int WIFI_MANAGER_TDLS_STATE_DISCONNECTED = 0;

  /// < Wi-Fi TDLS is Connected
  static const int WIFI_MANAGER_TDLS_STATE_CONNECTED = 1;
}

