    wifi_manager_config_h config, ffi.Pointer<ffi.Void> user_data);
typedef Dartwifi_manager_config_list_cbFunction = bool Function(
    wifi_manager_config_h config, ffi.Pointer<ffi.Void> user_data);

/// @brief Called when the Wi-Fi TDLS is discovered.
